const std = @import("std");
const llm = @import("llm.zig");

const Allocator = std.mem.Allocator;

const ServerContext = struct {
    allocator: Allocator,
    api_key: []const u8,
};

const listen_host: []const u8 = "0.0.0.0";
const listen_port: u16 = 5000;
const read_buffer_size: usize = 32  1024;
const max_request_body: usize = 4  1024  1024;

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();

    const allocator = gpa.allocator();

    const api_key = llm.getRequiredEnv(allocator, "HPC_AI_API_KEY") catch |err| {
        switch (err) {
            error.MissingRequiredEnv => std.debug.print("Missing required environment variable: HPC_AI_API_KEY\n", .{}),
            else => std.debug.print("Error retrieving environment variable: {s}\n", .{@errorName(err)}),
        }
        std.process.exit(1);
    };
    defer allocator.free(api_key);

    const ctx = ServerContext{ .allocator = allocator, .api_key = api_key };

    const address = try std.net.Address.parseIp4(listen_host, listen_port);
    var net_server = try address.listen(.{ .reuse_address = true });
    defer net_server.deinit();

    std.debug.print("zigllmbackend listening on ", .{ listen_host, listen_port });

    while (true) {
        const conn = net_server.accept() catch |err| {
            std.debug.print("accept error: {s}\n", .{@errorName(err)});
            continue;
        };

        const thread = std.Thread.spawn(.{}, handleConnection, .{ ctx, conn }) catch |err| {
            std.debug.print("spawn error: {s}\n", .{@errorName(err)});
            conn.stream.close();
            continue;
        };
        thread.detach();
    }
}

fn handleConnection(ctx: ServerContext, conn: std.net.Server.Connection) void {
    defer conn.stream.close();

    var read_buffer: [read_buffer_size]u8 = undefined;
    var server = std.http.Server.init(conn, &read_buffer);

    while (server.state == .ready) {
        var request = server.receiveHead() catch |err| {
            switch (err) {
                error.HttpConnectionClosing => {},
                else => std.debug.print("receiveHead error: {s}\n", .{@errorName(err)}),
            }
            return;
        };

        handleRequest(ctx, &request) catch |err| {
            std.debug.print("handleRequest error: {s}\n", .{@errorName(err)});
            sendErrorJson(&request, .internal_server_error, @errorName(err)) catch {};
            return;
        };
    }
}

fn handleRequest(ctx: ServerContext, request: std.http.Server.Request) !void {
    const target = request.head.target;
    const method = request.head.method;
    const path = if (std.mem.indexOfScalar(u8, target, '?')) |i| target[0..i] else target;

    if (method == .OPTIONS) {
        try request.respond("", .{
            .status = .no_content,
            .extra_headers = &cors_preflight_headers,
        });
        return;
    }

    if (method == .GET and (std.mem.eql(u8, path, "/") or std.mem.eql(u8, path, "/index.html"))) {
        try respondInfo(request);
        return;
    }

    if (method == .GET and std.mem.eql(u8, path, "/health")) {
        try request.respond("ok", .{
            .status = .ok,
            .extra_headers = &.{
                .{ .name = "contenttype", .value = "text/plain; charset=utf8" },
                .{ .name = "accesscontrolalloworigin", .value = "" },
                .{ .name = "cachecontrol", .value = "nostore" },
            },
        });
        return;
    }

    if (method == .POST and std.mem.eql(u8, path, "/chat")) {
        try handleChat(ctx, request);
        return;
    }

    try sendErrorJson(request, .not_found, "not found");
}

const cors_preflight_headers = [_]std.http.Header{
    .{ .name = "accesscontrolalloworigin", .value = "" },
    .{ .name = "accesscontrolallowmethods", .value = "GET, POST, OPTIONS" },
    .{ .name = "accesscontrolallowheaders", .value = "contenttype, authorization" },
    .{ .name = "accesscontrolmaxage", .value = "86400" },
};

fn respondInfo(request: std.http.Server.Request) !void {
    const body =
        "{\"name\":\"zigllmbackend\",\"model\":\"" ++ llm.model_name ++
        "\",\"endpoints\":{\"GET /health\":\"liveness probe\",\"POST /chat\":\"body {\\\"prompt\\\":\\\"...\\\"} returns {\\\"text\\\":\\\"...\\\"}\"}}";
    try request.respond(body, .{
        .status = .ok,
        .extra_headers = &.{
            .{ .name = "contenttype", .value = "application/json" },
            .{ .name = "accesscontrolalloworigin", .value = "" },
            .{ .name = "cachecontrol", .value = "nostore" },
        },
    });
}

fn handleChat(ctx: ServerContext, request: std.http.Server.Request) !void {
    const body_reader = try request.reader();
    const body = try body_reader.readAllAlloc(ctx.allocator, max_request_body);
    defer ctx.allocator.free(body);

    if (body.len == 0) {
        try sendErrorJson(request, .bad_request, "empty request body");
        return;
    }

    var parsed = std.json.parseFromSlice(std.json.Value, ctx.allocator, body, .{}) catch {
        try sendErrorJson(request, .bad_request, "invalid json");
        return;
    };
    defer parsed.deinit();

    if (parsed.value != .object) {
        try sendErrorJson(request, .bad_request, "expected json object");
        return;
    }

    const prompt_val = parsed.value.object.get("prompt") orelse {
        try sendErrorJson(request, .bad_request, "missing prompt field");
        return;
    };

    if (prompt_val != .string) {
        try sendErrorJson(request, .bad_request, "prompt must be a string");
        return;
    }

    const trimmed = std.mem.trim(u8, prompt_val.string, " \t\r\n");
    if (trimmed.len == 0) {
        try sendErrorJson(request, .bad_request, "prompt must not be empty");
        return;
    }

    const text = llm.complete(ctx.allocator, ctx.api_key, trimmed) catch |err| {
        const name = @errorName(err);
        std.debug.print("llm.complete error: {s}\n", .{name});
        try sendErrorJson(request, .bad_gateway, name);
        return;
    };
    defer ctx.allocator.free(text);

    var out = std.ArrayList(u8).init(ctx.allocator);
    defer out.deinit();

    try out.appendSlice("{\"text\":");
    try std.json.stringify(text, .{}, out.writer());
    try out.appendSlice(",\"model\":");
    try std.json.stringify(llm.model_name, .{}, out.writer());
    try out.appendSlice("}");

    try request.respond(out.items, .{
        .status = .ok,
        .extra_headers = &.{
            .{ .name = "contenttype", .value = "application/json" },
            .{ .name = "accesscontrolalloworigin", .value = "" },
            .{ .name = "cachecontrol", .value = "nostore" },
        },
    });
}

fn sendErrorJson(request: std.http.Server.Request, status: std.http.Status, message: []const u8) !void {
    var buf: [1024]u8 = undefined;
    var fbs = std.io.fixedBufferStream(&buf);
    const writer = fbs.writer();
    try writer.writeAll("{\"error\":");
    try std.json.stringify(message, .{}, writer);
    try writer.writeAll("}");

    try request.respond(fbs.getWritten(), .{
        .status = status,
        .keep_alive = false,
        .extra_headers = &.{
            .{ .name = "contenttype", .value = "application/json" },
            .{ .name = "accesscontrolalloworigin", .value = "" },
            .{ .name = "cachecontrol", .value = "nostore" },
        },
    });
}
